package android.os;import java.util.*;public class Handler {public static List<Runnable> queue=new ArrayList<>();public Handler(Looper l){}public boolean postDelayed(Runnable r,long d){queue.add(r);return true;}public boolean post(Runnable r){queue.add(r);return true;}public void removeCallbacks(Runnable r){queue.remove(r);}public static void fire(){List<Runnable> q=new ArrayList<>(queue);queue.clear();for(Runnable r:q)r.run();}}
